import java.util.*;
import java.io.*;

public class Cutting{

    public static int[] readIntArray(String s){
        String[] parts = s.trim().split("\\s+");
        int[] arr = new int[parts.length];
        for(int i=0; i<parts.length; i++){
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }

    boolean isBalanced(int[] array, int index){
        int evenCount = 0, oddCount = 0;
        for(int i=0; i<=index; i++){
            if(array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findCutPosition(int[] array, int coins, Map<Integer,Boolean> used){
        int position = -1;
        int minCost = coins + 1;
        for(int i=1; i<array.length - 1; i++){
            int cost = Math.abs(array[i] - array[i+1]);
            if(cost < minCost && isBalanced(array, i) && !used.containsKey(i)){
                minCost = cost;
                position = i;
            }
        }
        return position;
    }

    public int getMaximumCuts(int n, int b, int[] a){
        int remainingCoins = b;
        int totalCuts = 0;
        Map<Integer,Boolean> usedIndices = new HashMap<>();
        while(remainingCoins > 0){
            int cutPos = findCutPosition(a, remainingCoins, usedIndices);
            if(cutPos >= 0){
                usedIndices.put(cutPos, true);
                int cost = Math.abs(a[cutPos] - a[cutPos+1]);
                remainingCoins -= cost;
                totalCuts++;
            } else {
                break;
            }
        }
        return totalCuts;
    }

    public static void main(String[] args) throws Exception{
        Scanner sc = new Scanner(System.in);
        String line1 = sc.nextLine();
        String line2 = sc.nextLine();
        int[] nb = readIntArray(line1);
        int[] a = readIntArray(line2);
        Cutting c = new Cutting();
        int n = nb[0];
        int b = nb[1];
        System.out.println(c.getMaximumCuts(n, b, a));
        sc.close();
    }
}
