class Cutting:
    @staticmethod
    def read_int_array(s):
        parts = s.strip().split()
        return [int(part) for part in parts]

    def is_balanced(self, array, index):
        even_count = 0
        odd_count = 0
        for i in range(index + 1):
            if array[i] % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        return even_count == odd_count

    def find_cut_position(self, array, coins, used):
        position = -1
        min_cost = coins + 1
        for i in range(1, len(array) - 1):
            cost = abs(array[i] - array[i + 1])
            if cost < min_cost and self.is_balanced(array, i) and i not in used:
                min_cost = cost
                position = i
        return position

    def get_maximum_cuts(self, n, b, a):
        remaining_coins = b
        total_cuts = 0
        used_indices = set()
        while remaining_coins > 0:
            cut_pos = self.find_cut_position(a, remaining_coins, used_indices)
            if cut_pos >= 0:
                used_indices.add(cut_pos)
                cost = abs(a[cut_pos] - a[cut_pos + 1])
                remaining_coins -= cost
                total_cuts += 1
            else:
                break
        return total_cuts

if __name__ == "__main__":
    n_b_line = input()
    a_line = input()
    nb = Cutting.read_int_array(n_b_line)
    a = Cutting.read_int_array(a_line)
    c = Cutting()
    n = nb[0]
    b = nb[1]
    print(c.get_maximum_cuts(n, b, a))

